public class CommandDispatcherTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object run(Object target, String command, int a, int b) {
        try {
            return CommandDispatcher.dispatch(target, command, a, b);
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    public static void main(String[] args) {
        Object arithmetic = new ArithmeticCommands();
        Object range = new RangeCommands();

        check("add routes to plus", 5, run(arithmetic, "add", 2, 3));
        check("sub routes to minus", 6, run(arithmetic, "sub", 10, 4));
        check("mul routes to times", 42, run(arithmetic, "mul", 6, 7));
        check("an unknown command", "IllegalArgumentException: unknown command: div",
                run(arithmetic, "div", 8, 2));
        check("a method name is not a command", "IllegalArgumentException: unknown command: helper",
                run(arithmetic, "helper", 8, 2));
        check("max on a different target", 9, run(range, "max", 3, 9));
        check("min on a different target", 3, run(range, "min", 3, 9));
        check("commands are per-target", "IllegalArgumentException: unknown command: add",
                run(range, "add", 1, 1));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

