import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Method;

// Provided -- do not edit.
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Command {

    String value();
}

// Provided -- do not edit.
class ArithmeticCommands {

    @Command("add")
    int plus(int a, int b) {
        return a + b;
    }

    @Command("sub")
    int minus(int a, int b) {
        return a - b;
    }

    @Command("mul")
    int times(int a, int b) {
        return a * b;
    }

    int helper(int a, int b) {
        return 999;
    }
}

// Provided -- do not edit.
class RangeCommands {

    @Command("max")
    int biggest(int a, int b) {
        return Math.max(a, b);
    }

    @Command("min")
    int smallest(int a, int b) {
        return Math.min(a, b);
    }
}

public class CommandDispatcher {

    public static int dispatch(Object target, String command, int a, int b) {
        for (Method method : target.getClass().getDeclaredMethods()) {
            Command marker = method.getAnnotation(Command.class);
            if (marker != null && marker.value().equals(command)) {
                method.setAccessible(true);
                try {
                    return (Integer) method.invoke(target, a, b);
                } catch (ReflectiveOperationException e) {
                    throw new IllegalStateException("could not run " + command, e);
                }
            }
        }
        throw new IllegalArgumentException("unknown command: " + command);
    }
}
